            'images' => [
                'sidebar-blocks' => 'The sidebar with its blocks unfolded: Data foundation, Financial modelling, Risk & regulatory and Administration & support, the current page marked in its block colour',
                'sidebar-collapsed' => 'The sidebar folded to the icon rail: one icon per entry, thin lines between the blocks, and the Expand the menu button at the foot',
